<?php
declare(strict_types=1);
require __DIR__.'/harness.php';require __DIR__.'/database.php';require __DIR__.'/catalog-fixture.php';require __DIR__.'/commerce-fixture.php';
use Hostider\Commerce\{Services,CurrencyChanges};use Hostider\Core\Id;use Hostider\Core\Database\Migrator;use Hostider\Core\Http\HttpError;use Hostider\Finance\{Currency,Decimal,FxSnapshot,Money,Rounding};
$db=integrationDb();(new Migrator($db,dirname(__DIR__).'/migrations'))->migrate();$services=new Services($db,testConfig('test'));$admin=commerceAdmin($services);
function currencyFixture(): array {
    global $db,$services,$admin;$client=commerceUser($services,'currency');$assignment=$db->execute('SELECT id FROM identity_assignments WHERE user_id=? AND customer_id IS NULL LIMIT 1',[$admin['user']])->fetchColumn();$db->execute('INSERT INTO identity_grants(id,assignment_id,permission,customer_scope) VALUES (?,?,?,?)',[Id::uuid(),$assignment,'finance.approve',$client['customer']]);
    $actor=$services->identity->locked($client['reference'],'client',fn(array $u,array $s)=>$services->identity->principal($u,$s));$wallet=$db->transaction(fn()=>$services->finance->openWallet($client['customer'],new Currency('TRY'),$actor));
    $db->transaction(function()use($services,$client,$actor): void {$payment=$services->finance->recordTestCollection($client['customer'],new Money('22000',new Currency('TRY')),Id::uuid(),$actor,Id::uuid());$services->finance->creditWallet($client['customer'],$payment,new Money('22000',new Currency('TRY')),Id::uuid(),$actor,Id::uuid());});
    $db->transaction(fn()=>$services->fx->publishSynthetic(new FxSnapshot(new Currency('TRY'),new Currency('USD'),new Decimal('0.025'),new Decimal('0'),'synthetic-currency-conversion',new DateTimeImmutable('now',new DateTimeZone('UTC')),Rounding::HalfUp),true));
    return compact('client','actor','wallet');
}
test('FIN-009 approved currency conversion keeps one wallet and historical paid bill unchanged',function()use($db,$services,$admin): void {
    $f=currencyFixture();$client=$f['client'];$catalog=catalogFixture($db);$catalog['create']('price-publish',['item_id'=>$catalog['product'],'cycle_id'=>$catalog['cycle'],'currency'=>'TRY','amount'=>'100']);$cart=[['product_id'=>$catalog['product'],'cycle_id'=>$catalog['cycle'],'quantity'=>1]];
    $order=$db->transaction(function()use($services,$client,$cart,$f): array {$plan=$services->quotes->plan($client['customer'],new Currency('TRY'),$cart,[],new DateTimeImmutable('now',new DateTimeZone('UTC')));$quote=$services->quotes->issue($plan);$order=$services->orders->submit($quote['id'],$client['customer'],['name'=>'Synthetic historical billing','currency'=>'TRY'],$f['actor'],Id::uuid(),new DateTimeImmutable('now',new DateTimeZone('UTC')));$services->orders->fund($order['id'],$client['customer'],new Money('12000',new Currency('TRY')),'WALLET',null,Id::uuid(),$f['actor'],Id::uuid());return $order;});
    $before=$services->billing->detail($order['payment_request_id'],$client['customer']);raises(PDOException::class,fn()=>$db->execute('UPDATE finance_wallets SET currency=\'USD\' WHERE id=?',[$f['wallet']]));
    $review=commercePrepare($services,$admin,'admin','customer-currency',['currency'=>'USD'],$client['customer']);same('10000',$review['plan']['proposed']['original']['minor']);same('250',$review['plan']['proposed']['converted']['minor']);
    $result=commerceExecute($services,$admin,'admin','customer-currency',['currency'=>'USD'],$client['customer'],$review['id']);same('250',$result['converted']['minor']);same('USD',$services->identity->repository->customer($client['customer'])['currency']);same('USD',$services->finance->repository->wallet($client['customer'],false)['currency']);same('250',$services->finance->repository->balance($f['wallet']));same(1,(int)$db->execute('SELECT COUNT(*) FROM finance_wallets WHERE customer_id=?',[$client['customer']])->fetchColumn());same($before,$services->billing->detail($order['payment_request_id'],$client['customer']));
    same(401,raises(HttpError::class,fn()=>$services->identity->locked($client['reference'],'client',fn()=>null))->status);same(1,(int)$db->execute('SELECT COUNT(*) FROM finance_wallet_conversion_applications WHERE wallet_id=?',[$f['wallet']])->fetchColumn());
    $review=commercePrepare($services,$admin,'admin','order-refund',['request_id'=>$order['payment_request_id'],'minor'=>'6000'],$client['customer']);$result=commerceExecute($services,$admin,'admin','order-refund',['request_id'=>$order['payment_request_id'],'minor'=>'6000'],$client['customer'],$review['id']);same('TRY',$result['plan']['currency']);same('USD',$result['plan']['sources'][0]['wallet_credit']['currency']);same('150',$result['plan']['sources'][0]['wallet_credit']['minor']);same('400',$services->finance->repository->balance($f['wallet']));same('TRY',$services->billing->detail($order['payment_request_id'],$client['customer'])['currency']);
});
test('FIN-009 conversion rejects open attempts and rolls back both Identity and Finance on interruption',function()use($db,$services,$admin): void {
    $f=currencyFixture();$client=$f['client'];$staff=$services->identity->locked($admin['reference'],'admin',fn(array $u,array $s)=>$services->identity->principal($u,$s));
    raises(RuntimeException::class,fn()=>$db->transaction(function()use($services,$client,$staff): void {(new CurrencyChanges($services))->execute($client['customer'],'USD',$staff,Id::uuid());throw new RuntimeException('Interrupted account conversion');}));same('TRY',$services->identity->repository->customer($client['customer'])['currency']);same('TRY',$services->finance->repository->wallet($client['customer'],false)['currency']);same('22000',$services->finance->repository->balance($f['wallet']));$services->identity->locked($client['reference'],'client',fn()=>null);
    $db->transaction(fn()=>$services->payments->createAttempt($client['customer'],new Money('100',new Currency('TRY')),null,$f['actor'],Id::uuid()));same(409,raises(HttpError::class,fn()=>commercePrepare($services,$admin,'admin','customer-currency',['currency'=>'USD'],$client['customer']))->status);
});
runTests();
